rows=[[14],[0,2,4,6,8,10,13,15,17],[9,16],[0,8,16],[4,8],[15],[4,6,11,13],[7,16],[2,6,13,15],[7]]
R,C=10,19
a=[[7]*C for _ in range(R)]
for r,cs in enumerate(rows):
 for c in cs:a[r][c]=2
b=[row[:] for row in a]
# connect all markers sharing row/column, filling only between adjacent markers
for r,cs in enumerate(rows):
 for x,y in zip(cs,cs[1:]):
  for c in range(x+1,y):b[r][c]=3
for c in range(C):
 rs=[r for r in range(R) if a[r][c]==2]
 for x,y in zip(rs,rs[1:]):
  for r in range(x+1,y):b[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in b))
print('counts',sum(x==3 for row in b for x in row))
